import{_ as r,C as a,o as n,c as o,E as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse('{"title":"行业架构观察周报 001 — 企业 Agent 治理控制面正在形成","description":"","frontmatter":{"title":"行业架构观察周报 001 — 企业 Agent 治理控制面正在形成","date":"2026-08-02","column":"industry-architecture","category":"weekly","summary":"Workday、ServiceNow 与 Microsoft 正在形成相似的企业 Agent 治理控制面：统一发现和注册、明确 Owner、管理权限与生命周期、持续观察风险，并衡量成本与价值。","sources":["Workday Agent System of Record","ServiceNow AI Control Tower","Microsoft Agent 365"],"outline":"deep","cover":"/assets/covers/enterprise-agent-governance-control-plane-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-02-enterprise-agent-governance-control-plane.md","filePath":"zh/industry/2026-08-02-enterprise-agent-governance-control-plane.md","lastUpdated":1787407830000}'),l={name:"zh/industry/2026-08-02-enterprise-agent-governance-control-plane.md"};function c(d,e,g,h,p,u){const t=a("ArticleCover");return n(),o("div",null,[s(t,{image:"/assets/covers/enterprise-agent-governance-control-plane-cover-v2.jpg",kicker:"行业架构 · 观察周报 001",title:"企业 Agent 治理控制面正在形成",summary:"Workday、ServiceNow 与 Microsoft 的共同方向：发现、注册、治理、安全、观察与价值衡量。",version:"IW001",status:"发布于 2026-08-02",languageHref:"/en/industry/2026-08-02-enterprise-agent-governance-control-plane",languageLabel:"English"}),e[0]||(e[0]=i(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>本周最重要的行业架构信号，不是某个 Agent 的推理能力再次提高，而是企业开始建设位于模型、Agent Framework 和业务应用之上的统一治理控制面。</p><p>Workday 将 AI Agent 纳入混合劳动力的 System of Record；ServiceNow 将 AI Control Tower 扩展为发现、观察、治理、安全和衡量五个维度；Microsoft Agent 365 则通过 Agent Registry、Entra、Purview 和生命周期动作，把跨平台 Agent 纳入统一管理。</p><p>本报告的判断是：</p><blockquote><p>企业 Agent 治理正在从分散的产品设置，演进为独立的控制平面。其核心对象不是 Prompt，而是可发现、可归属、可授权、可观察、可停用和可衡量的组织资产。</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>本周入选三组官方资料：</p><ol><li><strong>Workday Agent System of Record（ASOR）</strong>：提供统一 Agent 清单、生命周期、责任、权限、交互计量与价值分析。</li><li><strong>ServiceNow AI Control Tower</strong>：把跨平台 AI 资产治理分为 Discover、Observe、Govern、Secure、Measure 五个维度。</li><li><strong>Microsoft Agent 365</strong>：通过 Agent Registry、Registry Sync、Owner、访问治理、激活、阻断和退役，形成企业 Agent 管理面。</li></ol><p>这些资料主要用于判断厂商公开的产品架构。厂商披露的客户规模、市场覆盖和价值提升属于厂商主张，不能替代独立实证。</p><h2 id="weekly-highlights" tabindex="-1">Weekly Highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly Highlights&quot;">​</a></h2><h3 id="_1-agent-registry-成为共同起点" tabindex="-1">1. Agent Registry 成为共同起点 <a class="header-anchor" href="#_1-agent-registry-成为共同起点" aria-label="Permalink to &quot;1. Agent Registry 成为共同起点&quot;">​</a></h3><p>三个体系都首先解决“组织里到底有哪些 Agent”。</p><ul><li>Workday ASOR 注册 Workday、客户和第三方 Agent；</li><li>ServiceNow AI Control Tower 自动发现 Agent、模型、Identity、Workflow、MCP Server 和其他 AI 资产；</li><li>Microsoft Agent Registry 可以同步外部 Agent 环境，形成集中可见性。</li></ul><p>这说明企业 Agent 治理的第一步不是编排，而是资产发现与身份建立。</p><h3 id="_2-owner-与生命周期进入正式治理" tabindex="-1">2. Owner 与生命周期进入正式治理 <a class="header-anchor" href="#_2-owner-与生命周期进入正式治理" aria-label="Permalink to &quot;2. Owner 与生命周期进入正式治理&quot;">​</a></h3><p>Workday 将 Agent 生命周期描述为 register、configure、activate、deactivate，并强调责任与问责。Microsoft 提供 Owner 分配、安装、激活、阻断、重新分配和删除等动作。ServiceNow 则把 AI Asset Owner、风险团队和 AI Steward 放进统一控制流程。</p><p>Agent 因此开始像服务账户、应用和员工岗位一样，拥有持续存在的治理状态。</p><h3 id="_3-运行期观察替代一次性审核" tabindex="-1">3. 运行期观察替代一次性审核 <a class="header-anchor" href="#_3-运行期观察替代一次性审核" aria-label="Permalink to &quot;3. 运行期观察替代一次性审核&quot;">​</a></h3><p>ServiceNow 明确把持续观测、实时指标、行为 Trace 和告警放进控制面；Workday 通过 Agent Gateway 对交互进行管理和计量；Microsoft 将身份、数据与威胁防护延伸到 Agent。</p><p>治理正在从“上线前审批”转向“上线前验证 + 运行中持续判断”。</p><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="三个平台的控制面能力矩阵" tabindex="-1">三个平台的控制面能力矩阵 <a class="header-anchor" href="#三个平台的控制面能力矩阵" aria-label="Permalink to &quot;三个平台的控制面能力矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力维度</th><th>Workday ASOR</th><th>ServiceNow AI Control Tower</th><th>Microsoft Agent 365</th></tr></thead><tbody><tr><td>统一清单 / Registry</td><td>第一方、第三方 Agent</td><td>Agent、模型、Identity、Workflow、MCP 等</td><td>第一方与外部 Agent Registry</td></tr><tr><td>Owner / 责任</td><td>强调角色、责任与问责</td><td>AI Asset Owner、Steward 与风险流程</td><td>Owner 分配与重新分配</td></tr><tr><td>生命周期</td><td>注册、配置、激活、停用</td><td>发现、评估、治理与处置</td><td>安装、激活、阻断、删除</td></tr><tr><td>权限与身份</td><td>精确身份与权限，Agent Gateway</td><td>Identity Access Governance、最小权限、Kill Switch</td><td>Entra 身份、Access Package、策略</td></tr><tr><td>运行观察</td><td>Interaction Metering 与 Analytics</td><td>Runtime Trace、指标、告警与行为观察</td><td>Agent Map、风险与安全监控</td></tr><tr><td>成本与价值</td><td>成本、影响与动态 ROI</td><td>成本跟踪与 ROI Dashboard</td><td>重点偏治理、安全与合规</td></tr><tr><td>主要组织入口</td><td>HCM / Finance / Blended Workforce</td><td>IT Governance / CMDB / Workflow</td><td>Microsoft 365 / Entra / Purview</td></tr></tbody></table><p><strong>说明：</strong> 表格依据三家官方公开能力整理，不代表独立性能评测，也不表示各项能力成熟度相同。</p><h3 id="控制面共同结构" tabindex="-1">控制面共同结构 <a class="header-anchor" href="#控制面共同结构" aria-label="Permalink to &quot;控制面共同结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>企业中的 Agent、模型与运行环境</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>      Discover / Register</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span> Identity + Owner + Position</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span> Policy + Access + Lifecycle</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span> Observe + Risk + Cost + Value</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>  Block / Retire / Improve / Audit</span></span></code></pre></div><p><em>图示：joinwell52 Research Center 根据官方资料整理。</em></p><h3 id="控制面不等于工作-runtime" tabindex="-1">控制面不等于工作 Runtime <a class="header-anchor" href="#控制面不等于工作-runtime" aria-label="Permalink to &quot;控制面不等于工作 Runtime&quot;">​</a></h3><p>三家平台都在加强治理，但控制面主要回答：</p><ul><li>有哪些 Agent；</li><li>谁负责；</li><li>有什么权限；</li><li>是否合规；</li><li>当前风险、成本和价值如何；</li><li>是否应该激活、阻断或退役。</li></ul><p>它并不完整回答某个 WorkOrder 如何被拆解、执行、恢复、举证和完成。因此，控制面与工作 Runtime 应分开建模，通过稳定契约连接。</p><h2 id="new-architecture-judgment" tabindex="-1">New Architecture Judgment <a class="header-anchor" href="#new-architecture-judgment" aria-label="Permalink to &quot;New Architecture Judgment&quot;">​</a></h2><p>本周形成四个架构判断：</p><ol><li><strong>Agent Registry 将成为企业 AI 基础设施。</strong> 没有清单就无法治理跨平台 Agent。</li><li><strong>Owner 是治理链的入口。</strong> Owner 连接审批、权限、风险处置、成本和停用责任。</li><li><strong>身份与权限必须独立于模型 Provider。</strong> Agent 可能更换模型与运行环境，但组织身份不能随 Session 消失。</li><li><strong>持续观察将成为正式治理条件。</strong> 静态合规文件不能替代运行时 Trace、行为和风险状态。</li></ol><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本报告不直接修改 TMPA 正式文档。作为研究输入，它强化了 Profile、Authority、Lifecycle、Event、Integrity 与 Governance Judgment 之间必须存在可追溯 Reference 的必要性。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>数字员工控制面至少需要：</p><ul><li>Registry；</li><li>Position 与 Owner；</li><li>Authority Policy；</li><li>Lifecycle；</li><li>Provider / Tool Binding；</li><li>Runtime Health；</li><li>Cost / Value / Evaluation；</li><li>Audit 与处置动作。</li></ul><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 当前具备较强的 Work Runtime 事实，但缺少独立控制面。合理顺序是先建立只读 Registry 投影，再逐步加入 Owner、生命周期、权限和健康处置，而不是重写现有任务执行链。</p><h2 id="next-week-research" tabindex="-1">Next Week Research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next Week Research&quot;">​</a></h2><ol><li>对照 SAP、Oracle、Salesforce 的 Agent Builder 与运行治理。</li><li>研究控制面和 Runtime 之间的最小接口。</li><li>比较企业平台中的 Kill Switch、人工升级和恢复策略。</li><li>继续验证中小企业是否需要完整 Control Tower，或只需要最小治理平面。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday, <strong>Agent System of Record</strong>: <a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday, <strong>The Workday Agent System of Record Is Now Generally Available</strong>: <a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday, <strong>What are AI agents?</strong>: <a href="https://www.workday.com/en-us/topics/ai/ai-agents.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/ai/ai-agents.html</a></li><li>ServiceNow, <strong>AI Control Tower</strong>: <a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li><li>ServiceNow, <strong>AI Control Tower expands across the enterprise</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx</a></li><li>Microsoft Learn, <strong>Microsoft Agent 365 overview</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn, <strong>Registry sync in the Microsoft 365 agent registry</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry</a></li><li>Microsoft Learn, <strong>Govern agents using Agent 365</strong>: <a href="https://learn.microsoft.com/en-us/training/modules/agent-365-govern/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/training/modules/agent-365-govern/</a></li></ol>`,46))])}const f=r(l,[["render",c]]);export{w as __pageData,f as default};
